import urllib.request, json, re, html

payload = json.dumps({
    "context": {
        "client": {
            "clientName": "ANDROID",
            "clientVersion": "19.09.37",
            "androidSdkVersion": 30,
            "hl": "en",
            "gl": "US"
        }
    },
    "videoId": "40uRWuhfZI0"
}).encode("utf-8")

req = urllib.request.Request(
    "https://www.youtube.com/youtubei/v1/player?prettyPrint=false",
    data=payload,
    headers={"Content-Type": "application/json", "User-Agent": "com.google.android.youtube/19.09.37 (Linux; U; Android 11) gzip"}
)
resp = json.loads(urllib.request.urlopen(req, timeout=10).read().decode("utf-8", errors="ignore"))
tracks = resp.get("captions", {}).get("playerCaptionsTracklistRenderer", {}).get("captionTracks", [])
print("Tracks found:", len(tracks))
en_track = next((t for t in tracks if t.get("languageCode") == "en"), tracks[0] if tracks else None)
if en_track:
    xml_data = urllib.request.urlopen(urllib.request.Request(en_track["baseUrl"], headers={"User-Agent": "com.google.android.youtube/19.09.37 (Linux; U; Android 11) gzip"}), timeout=10).read().decode("utf-8", errors="ignore")
    matches = re.findall(r"<p t=\"(\d+)\"[^>]*>(.*?)</p>", xml_data, re.DOTALL)
    if not matches:
        matches = [(str(int(float(m[0])*1000)), m[1]) for m in re.findall(r"<text start=\"([\d\.]+)\"[^>]*>(.*?)</text>", xml_data, re.DOTALL)]
    out_lines = []
    for ms, txt in matches:
        sec = int(ms) // 1000
        clean = html.unescape(re.sub(r"<[^>]+>", "", txt)).strip()
        if clean:
            out_lines.append(f"[{sec//60:02d}:{sec%60:02d}] {clean}")
    full_t = "\n".join(out_lines)
    with open("/home/user/.gemini/antigravity/brain/092f7d00-e0a7-4cec-be77-f8cff1234933/scratch/yt_transcript.txt", "w") as f:
        f.write(full_t)
    print("Saved transcript lines:", len(out_lines))
    print(full_t[:3500])
'

