function postJsonWithLongTimeout(urlStr, bodyObj, timeoutMs = 600000) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr);
    const bodyStr = JSON.stringify(bodyObj);
    const req = http.request(
      {
        hostname: u.hostname,
        port: u.port || 80,
        path: u.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(bodyStr),
        },
        timeout: timeoutMs,
      },
      (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          try {
            const raw = Buffer.concat(chunks).toString('utf8');
            resolve({ status: res.statusCode, payload: JSON.parse(raw) });
          } catch (e) {
            reject(e);
          }
        });
      }
    );
    req.on('timeout', () => {
      req.destroy(new Error('HTTP Request Timeout'));
    });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

async function callFlow(method, args = [], retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const { status, payload } = await postJsonWithLongTimeout(`${BRIDGE_URL}/api/flow`, { method, args });
      if (status !== 200 || !payload.ok) {
        throw new Error(payload.error || `Lỗi gọi Flow.${method}`);
      }
      return payload.data;
    } catch (err) {
      console.warn(`   ⚠️ Lần thử ${attempt}/${retries} thất bại (${err.message}). Đang thử lại sau 4s...`);
      if (attempt === retries) throw err;
      await new Promise((r) => setTimeout(r, 4000));
    }
  }
}

